#include <stdio.h>
#include <stdlib.h>

typedef struct Object {
    int marked;
    struct Object *children[3];
} Object;

Object *heap[1024];
int heap_count = 0;

Object* obj_new() {
    Object *o = (Object*)calloc(1, sizeof(Object));
    heap[heap_count++] = o;
    return o;
}

void mark(Object *o) {
    if (!o || o->marked) return;
    o->marked = 1;
    for (int i = 0; i < 3; i++) mark(o->children[i]);
}

void sweep() {
    int alive = 0;
    for (int i = 0; i < heap_count; i++) {
        if (heap[i]->marked) {
            heap[i]->marked = 0;
            heap[alive++] = heap[i];
        } else {
            free(heap[i]);
        }
    }
    heap_count = alive;
}

int main() {
    Object *root = obj_new();
    root->children[0] = obj_new();
    root->children[1] = obj_new();
    obj_new(); // orphan!
    mark(root);
    int before = heap_count;
    sweep();
    printf("Before: %d, After: %d\n", before, heap_count);
    return 0;
}
